import pyomo.environ as pyo

DATA = {
    "products": ["fertilizer", "seeds"],
    "time_per_unit": {"fertilizer": 0.5, "seeds": 1.5},
    "total_units_max": 300,
    "fertilizer_min": 50,
    "fertilizer_to_seeds_ratio_max": 2,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=d["products"])

    def amount_bounds(m, p):
        return (0, d["total_units_max"])

    model.amount = pyo.Var(
        model.P, domain=pyo.NonNegativeReals, bounds=amount_bounds
    )

    def obj_rule(m):
        return sum(d["time_per_unit"][p] * m.amount[p] for p in m.P)

    model.obj = pyo.Objective(expr=obj_rule, sense=pyo.minimize)

    def total_units_rule(m):
        return sum(m.amount[p] for p in m.P) <= d["total_units_max"]

    model.total_units = pyo.Constraint(rule=total_units_rule)

    def fertilizer_min_rule(m):
        return m.amount["fertilizer"] >= d["fertilizer_min"]

    model.fertilizer_min = pyo.Constraint(rule=fertilizer_min_rule)

    def fertilizer_seeds_ratio_rule(m):
        return (
            m.amount["fertilizer"]
            <= d["fertilizer_to_seeds_ratio_max"] * m.amount["seeds"]
        )

    model.fertilizer_seeds_ratio = pyo.Constraint(rule=fertilizer_seeds_ratio_rule)

    return model


